{
  "tasks": [
    {
      "task_id": "T01",
      "title": "项目任务总体概况",
      "business_question": "当前数据集包含多少条任务记录？涉及多少个不同的项目和状态？",
      "priority": "P0",
      "priority_reason": "删除此任务将无法建立数据基线，无法回答“主要分布”的基础规模问题，属于核心探索需求。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_tasks"
              },
              {
                "function": "distinct_count",
                "field": "field_0002",
                "alias": "unique_projects"
              },
              {
                "function": "distinct_count",
                "field": "field_0003",
                "alias": "unique_statuses"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "按项目分布的任务数量与工时统计",
      "business_question": "各项目的任务数量是多少？各项目的平均工时、总工时及最大/最小工时分别是多少？以识别项目在规模和投入上的差异。",
      "priority": "P0",
      "priority_reason": "这是“探索主要分布与差异”的核心维度。通过分组聚合直接揭示不同项目间的资源分配不均或规模差异，若缺失则无法进行有效的业务对比分析。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              },
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              },
              {
                "function": "max",
                "field": "field_0004",
                "alias": "max_hours"
              },
              {
                "function": "min",
                "field": "field_0004",
                "alias": "min_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "task_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "按状态分布的任务数量与工时特征",
      "business_question": "各状态下的任务数量分布如何？不同状态任务的平均工时是否存在显著差异？",
      "priority": "P1",
      "priority_reason": "补充性分析。虽然项目是主要对象，但状态反映了流程健康度。删除后仍可回答核心问题（项目分布），但会降低对执行效率差异的洞察质量。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "status_task_count"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "status_avg_hours"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "status_task_count",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
